def max_bracketed_expression(expression):
    @lru_cache(None)
    def evaluate(expr):
        if '*' not in expr:
            return int(expr)
        parts = expr.split('*')
        return sum(evaluate(part) for part in parts)

    def insert_brackets(expr):
        if len(expr) <= 2:
            return [expr]
        result = []
        for i in range(1, len(expr)):
            if expr[i] == '+':
                left = insert_brackets(expr[:i])
                right = insert_brackets(expr[i+1:])
                for l in left:
                    for r in right:
                        result.append(f'({l}){expr[i]}({r})')
        return result

    brackets_expr = insert_brackets(expression)
    max_value = 0
    for expr in brackets_expr:
        max_value = max(max_value, evaluate(expr))
    return max_value

